class Point(object):
    def __new__(cls, x, y, srid=None):
        self = super(Point, cls).__new__(cls)
        self.x = x
        self.y = y
        self.srid = srid
        return self

    def __init__(self, x, y, srid=None):
        self.x = x
        self.y = y
        self.srid = srid

    # Convert string to integer
    def __str__(self):
        srid = int(self.srid)
        if srid == 4326:
            return (str(self.x) + ", " + str(self.y))
        elif srid == 3857:
            return (str(self.x) + ", " + str(self.y) + " (Spherical Mecator)")
        else:
            return (str(self.x) + ", " + str(self.y) + " (SRID " + str(self.srid) + ")")

    # Convert to tuple
    def __tuple__(self):
        return (self.x, self.y, self.srid)

    # Convert to list
    def __list__(self):
        return [self.x, self.y, self.srid]

    # Convert to dictionary
    def __dict__(self):
        return {"x": self.x, "y": self.y, "srid": self.srid}

