def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")

    if fixity is None:
        raise ValueError("fixity cannot be None")

    # Check the structure of the fixity block
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")

    # Check that all referenced files are listed in the manifest
    for file_path, checksum in fixity.items():
        if not isinstance(file_path, str):
            raise ValueError("file_path must be a string")

        if not isinstance(checksum, str):
            raise ValueError("checksum must be a string")

        if file_path not in manifest_files:
            raise ValueError("file_path not found in manifest")

    return True

