def string_to_int(string: str, alphabet: List[str]) -> int:
    if not isinstance(string, str):
        raise ValueError("string must be a string")
    if not isinstance(alphabet, list):
        raise ValueError("alphabet must be a list")

    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two elements")

    inverse_alphabet = dict(zip(alphabet, range(0, base)))

    n = 0
    exp = 0
    for i in reversed(string):
        n += inverse_alphabet[i] * (base ** exp)
        exp += 1

    return n

