    if frequency is None or frequency.lower() == "always":
        return None
    parts = frequency.lower().split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency: {}".format(frequency))
    quantity, unit = parts
    try:
        quantity = int(quantity)
    except ValueError:
        raise ValueError("Invalid quantity: {}".format(quantity))
    if unit == "year":
        return datetime.timedelta(days=quantity * 365)
    elif unit == "month":
