def run_command(commands, args, *, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Wrap the given command(s) in a list if necessary
    if isinstance(commands, str):
        commands = [commands]

    # Generate the full command to be run
    cmd = commands + [arg.replace("'", r"\'") for arg in args]

    # Build the subprocess arguments
    args = {'shell': True, 'stdout': subprocess.PIPE, 'stderr': subprocess.PIPE}
    if hide_stderr:
        args['stderr'] = subprocess.DEVNULL
    if cwd is not None:
        args['cwd'] = cwd
    if env is not None:
        args['env'] = env

    # Run the command
    with subprocess.Popen(cmd, **args) as proc:
        output = []
        while True:
            line = proc.stdout.readline()
            if not line:
                break
            output.append(line.decode('utf-8').rstrip('\n'))

        if verbose:
            print(' '.join(commands + args))

    return output

