def get_spec_defaults(self):
    spec = self.spec or {}
    defaults = {}
    for arg in spec.get('arg', []):
        if "Option" in arg["type"]
            if "default" in arg:
                defaults[arg["name"]] = arg["default"]
        elif "Dict" in arg["type"]:
            if arg["scheme"]:
                defaults[arg["name"]] = arg["scheme"].get_spec_defaults()

    return defaults

