def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    args = tuple(args)
    num_args = len(args)

    if num_args != 2:
        raise TypeError("Exactly two arguments expected, got %s." % num_args)

    min_value, max_value = args

    if min_value > max_value:
        raise ValueError("Minimum value must be less than or equal to maximum value.")

    if not isinstance(min_value, int) or not isinstance(max_value, int):
        raise TypeError("Both values must be integers.")

    if min_value < 0 or max_value < 0:
        raise ValueError("Both values must be non-negative.")

    return args

