def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = {}
    try:
        with open(f"{plugin_dir}/plugin.yml", "r") as f:
            plugin_spec = yaml.safe_load(f.read())
    except FileNotFoundError:
        print(f"Could not find plugin.yml file in {plugin_dir}.")
        return {}

    flatten_dict = {}
    for key, val in plugin_spec.items():
        if isinstance(val, dict):
            for sub_key, sub_val in val.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_val
        else:
            flatten_dict[key] = val

    return flatten_dict

